#!/usr/bin/env node
import assert from 'node:assert/strict';import fs from 'node:fs';import path from 'node:path';import {verify,verifyWire} from './capture.mjs';
const [left,right,out]=process.argv.slice(2);assert.ok(left&&right&&out&&!fs.existsSync(out));
const read=dir=>JSON.parse(fs.readFileSync(path.join(dir,'results.json')));
function project(row){const headers={...row.upgrades[0].headers};headers.host='<mock-host>';headers['sec-websocket-key']='<random-key>';if(headers.origin)headers.origin='<mock-origin>';const normalize=value=>{const frame=JSON.parse(value);if(frame.type==='call_service'){assert.match(frame.service_data.notification_id,/^gw_\d+$/);frame.service_data.notification_id='gw_<time>';}return frame;};return {channel:row.channel,fragmented:row.fragmented,headers,path:row.upgrades[0].path,extension:row.negotiatedExtensions,serverMessages:row.serverMessages.map(message=>({opcode:message.opcode,compressed:message.compressed,text:message.text})),clientMessages:row.clientMessages.map(message=>({opcode:message.opcode,compressed:message.compressed,value:normalize(message.text)})),wireShapes:{incoming:row.inboundFrames.map(f=>[f.fin,f.rsv1,f.rsv2,f.rsv3,f.opcode,f.masked,f.payloadLength]),outgoing:row.outboundFrames.map(f=>[f.fin,f.rsv1,f.rsv2,f.rsv3,f.opcode,f.masked,f.payloadLength])},exit:row.exit,stderr:row.stderr,forceKilled:row.forceKilled};}
const a=read(left),b=read(right);for(const rows of [a,b]){assert.deepEqual(rows.map(r=>r.channel),['mattermost','homeassistant']);for(const row of rows){assert.equal(row.valid,true);await verifyWire(row);verify(row);}}
assert.deepEqual(a.map(project),b.map(project));const controls=[];
for(const [name,index,mutate] of [['extension-offer',0,r=>r.upgrades[0].headers['sec-websocket-extensions']=''],['default-header',0,r=>delete r.upgrades[0].headers['accept-language']],['compressed-text-flag',0,r=>r.serverMessages.find(m=>m.opcode===1&&m.text.includes('compressed-wire-message')).compressed=false],['binary-processed',0,r=>r.models.push({body:'{"messages":[{"role":"user","content":"binary-must-ignore"}],"stream":true}'})],['ha-outbound-compressed',1,r=>r.clientMessages.at(-1).compressed=true],['decoded-answer',1,r=>r.received.find(f=>f.value.type==='call_service').value.service_data.message='wrong']]){const row=structuredClone(a[index]);mutate(row);assert.throws(()=>verify(row),undefined,name);controls.push({name,rejected:true});}
const corrupt=structuredClone(a[0]);corrupt.rawOutgoing[corrupt.rawOutgoing.length-1]=Buffer.from([255]).toString('base64');await assert.rejects(()=>verifyWire(corrupt));controls.push({name:'raw-wire-corrupt',rejected:true});
fs.writeFileSync(out,JSON.stringify({valid:true,baseline:'cc7c4e653b15c8b2cec7bcf2d15d41d69396ae85',cases:a.map(row=>({channel:row.channel,fragmented:row.fragmented})),contract:a.map(project),negativeControls:controls,normalization:'仅随机host/Origin/Sec-WebSocket-Key、HA notification_id毫秒；原始mask/accept/所有TCP字节保留且重新解析/有状态解压核对。'},null,2)+'\n');console.log('formal WS pair self-compare equal; 7 negative controls rejected');
